-- Brewway Production Baseline Migration
-- Generated from live Brewway Supabase database (project: xgvzsszzmlenkzyjtyyf)
-- This is the factual schema baseline for first customer production deployment.
-- Do NOT edit this file after generation. Hardening changes go in a separate migration.

-- =============================================================================
-- ENUM TYPES
-- =============================================================================

CREATE TYPE public.store_role AS ENUM ('owner', 'manager', 'staff');

CREATE TYPE public.order_status AS ENUM ('draft', 'pending_payment', 'paid', 'accepted', 'preparing', 'ready_for_pickup', 'completed', 'cancelled');

CREATE TYPE public.payment_status AS ENUM ('unpaid', 'pending', 'paid', 'rejected', 'refunded');

CREATE TYPE public.stock_movement_type AS ENUM ('in', 'out', 'adjustment', 'restore');

CREATE TYPE public.channel_fee_type AS ENUM ('none', 'percent', 'fixed');

-- =============================================================================
-- TABLES (in dependency order)
-- =============================================================================

CREATE TABLE public.stores (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name text NOT NULL,
    currency text NOT NULL DEFAULT 'THB',
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.profiles (
    id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    store_id uuid REFERENCES public.stores(id) ON DELETE SET NULL,
    email text NOT NULL,
    full_name text,
    role text NOT NULL DEFAULT 'staff' CHECK (role = ANY (ARRAY['owner'::text, 'admin'::text, 'staff'::text])),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.store_members (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    role public.store_role NOT NULL DEFAULT 'staff',
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.product_categories (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    name text NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.products (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    category_id uuid REFERENCES public.product_categories(id) ON DELETE SET NULL,
    name text NOT NULL,
    description text,
    image_url text,
    base_price numeric NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    is_special boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    allow_sweetness boolean NOT NULL DEFAULT false,
    default_sweetness integer NOT NULL DEFAULT 0 CHECK (default_sweetness = ANY (ARRAY[0, 25, 50, 75, 100])),
    allow_extra_shot boolean NOT NULL DEFAULT false,
    extra_shot_price numeric NOT NULL DEFAULT 0 CHECK (extra_shot_price >= 0::numeric),
    max_extra_shots integer NOT NULL DEFAULT 0 CHECK (max_extra_shots >= 0),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.ingredients (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    name text NOT NULL,
    unit text NOT NULL,
    cost_per_unit numeric(12,4) NOT NULL DEFAULT 0,
    current_stock numeric(12,4) NOT NULL DEFAULT 0,
    low_stock_threshold numeric(12,4) NOT NULL DEFAULT 0,
    supplier_name text,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    cost_type text NOT NULL DEFAULT 'ingredient' CHECK (cost_type = ANY (ARRAY['ingredient'::text, 'packaging'::text, 'consumable'::text, 'addon'::text, 'utility'::text, 'other'::text])),
    updated_at timestamptz NOT NULL DEFAULT now(),
    cost_source text NOT NULL DEFAULT 'manual' CHECK (cost_source = ANY (ARRAY['manual'::text, 'purchase_derived'::text, 'estimated'::text, 'migration'::text])),
    last_purchase_at timestamptz,
    cost_updated_at timestamptz
);

CREATE TABLE public.recipes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
    ingredient_id uuid NOT NULL REFERENCES public.ingredients(id) ON DELETE RESTRICT,
    quantity_used numeric(12,4) NOT NULL DEFAULT 0,
    unit text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.product_addons (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id),
    product_id uuid NOT NULL REFERENCES public.products(id),
    name text NOT NULL,
    code text NOT NULL,
    addon_type text NOT NULL DEFAULT 'extra_shot',
    price numeric NOT NULL DEFAULT 0 CHECK (price >= 0::numeric),
    max_quantity integer NOT NULL DEFAULT 1 CHECK (max_quantity >= 0),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.product_addon_recipes (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id),
    addon_id uuid NOT NULL REFERENCES public.product_addons(id),
    ingredient_id uuid NOT NULL REFERENCES public.ingredients(id),
    quantity_used numeric NOT NULL DEFAULT 0 CHECK (quantity_used >= 0::numeric),
    unit text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.sales_channels (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    name text NOT NULL,
    type text NOT NULL DEFAULT 'direct' CHECK (type = ANY (ARRAY['direct'::text, 'delivery'::text, 'manual'::text])),
    fee_type text NOT NULL DEFAULT 'none' CHECK (fee_type = ANY (ARRAY['none'::text, 'percent'::text, 'fixed'::text])),
    fee_value numeric(12,4) NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.channel_prices (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
    channel_id uuid NOT NULL REFERENCES public.sales_channels(id) ON DELETE CASCADE,
    price numeric(12,2) NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.customers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    line_user_id text,
    display_name text,
    phone text,
    total_orders integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.orders (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    order_no text NOT NULL,
    customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,
    channel_id uuid REFERENCES public.sales_channels(id) ON DELETE SET NULL,
    order_type text NOT NULL DEFAULT 'manual' CHECK (order_type = ANY (ARRAY['pickup'::text, 'delivery'::text, 'manual'::text])),
    pickup_time timestamptz,
    status text NOT NULL DEFAULT 'draft' CHECK (status = ANY (ARRAY['draft'::text, 'pending_payment'::text, 'waiting_payment_review'::text, 'accepted'::text, 'preparing'::text, 'ready'::text, 'completed'::text, 'cancelled'::text, 'voided'::text])),
    payment_status text NOT NULL DEFAULT 'unpaid' CHECK (payment_status = ANY (ARRAY['unpaid'::text, 'pending_review'::text, 'paid'::text, 'rejected'::text, 'refunded'::text])),
    subtotal numeric NOT NULL DEFAULT 0,
    channel_fee numeric NOT NULL DEFAULT 0,
    total_amount numeric NOT NULL DEFAULT 0,
    total_cost numeric NOT NULL DEFAULT 0,
    gross_profit numeric NOT NULL DEFAULT 0,
    note text,
    created_at timestamptz NOT NULL DEFAULT now(),
    channel text NOT NULL DEFAULT 'web_order',
    order_status text NOT NULL DEFAULT 'pending_payment' CHECK (order_status = ANY (ARRAY['draft'::text, 'pending_payment'::text, 'waiting_payment_review'::text, 'accepted'::text, 'preparing'::text, 'ready'::text, 'completed'::text, 'cancelled'::text, 'voided'::text])),
    pickup_type text NOT NULL DEFAULT 'pickup',
    discount_amount numeric NOT NULL DEFAULT 0,
    customer_note text,
    admin_note text,
    cancelled_reason text,
    cancelled_at timestamptz,
    updated_at timestamptz NOT NULL DEFAULT now(),
    customer_name text,
    customer_phone text,
    order_source text NOT NULL DEFAULT 'web_order',
    public_token text
);

CREATE TABLE public.order_items (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
    product_id uuid REFERENCES public.products(id) ON DELETE SET NULL,
    quantity integer NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price numeric(12,2) NOT NULL DEFAULT 0,
    unit_cost numeric(12,2) NOT NULL DEFAULT 0,
    total_price numeric(12,2) NOT NULL DEFAULT 0,
    total_cost numeric(12,2) NOT NULL DEFAULT 0,
    note text,
    created_at timestamptz NOT NULL DEFAULT now(),
    product_name_snapshot text NOT NULL,
    line_profit numeric(12,2) NOT NULL DEFAULT 0,
    options jsonb NOT NULL DEFAULT '{}'::jsonb,
    option_total numeric(12,2) NOT NULL DEFAULT 0 CHECK (option_total >= 0::numeric),
    option_cost_total numeric(12,2) NOT NULL DEFAULT 0 CHECK (option_cost_total >= 0::numeric),
    CHECK (unit_price >= 0::numeric AND unit_cost >= 0::numeric AND total_price >= 0::numeric AND total_cost >= 0::numeric AND line_profit >= 0::numeric)
);

CREATE TABLE public.payments (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
    method text NOT NULL DEFAULT 'transfer' CHECK (method = ANY (ARRAY['transfer'::text, 'bank_transfer'::text, 'promptpay'::text, 'cash'::text, 'other'::text])),
    amount numeric(12,2) NOT NULL DEFAULT 0 CHECK (amount >= 0::numeric),
    status text NOT NULL DEFAULT 'pending' CHECK (status = ANY (ARRAY['pending'::text, 'pending_review'::text, 'paid'::text, 'rejected'::text, 'refunded'::text])),
    slip_url text,
    confirmed_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    confirmed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,
    slip_file_name text,
    slip_storage_path text,
    submitted_at timestamptz,
    reject_reason text,
    verified_by_api boolean NOT NULL DEFAULT false,
    verification_provider text,
    verification_status text,
    verification_score numeric(5,2),
    api_response jsonb,
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.ingredient_purchases (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    ingredient_id uuid NOT NULL REFERENCES public.ingredients(id) ON DELETE RESTRICT,
    quantity numeric NOT NULL CHECK (quantity > 0::numeric),
    purchase_unit text NOT NULL,
    conversion_factor numeric NOT NULL DEFAULT 1 CHECK (conversion_factor > 0::numeric),
    normalized_quantity numeric NOT NULL CHECK (normalized_quantity > 0::numeric),
    base_unit_snapshot text,
    total_cost numeric NOT NULL CHECK (total_cost >= 0::numeric),
    unit_cost_snapshot numeric NOT NULL DEFAULT 0 CHECK (unit_cost_snapshot >= 0::numeric),
    supplier_name text,
    payment_status text NOT NULL DEFAULT 'paid' CHECK (payment_status = ANY (ARRAY['paid'::text, 'unpaid'::text, 'cancelled'::text])),
    paid_at timestamptz,
    due_date timestamptz,
    receipt_url text,
    receipt_storage_path text,
    note text,
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    is_perishable boolean NOT NULL DEFAULT false,
    lot_code text,
    expires_at timestamptz
);

CREATE TABLE public.stock_movements (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    ingredient_id uuid NOT NULL REFERENCES public.ingredients(id) ON DELETE CASCADE,
    movement_type text NOT NULL CHECK (movement_type = ANY (ARRAY['in'::text, 'used'::text, 'adjust'::text, 'return'::text])),
    quantity numeric NOT NULL,
    ref_order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL,
    note text,
    created_at timestamptz NOT NULL DEFAULT now(),
    purchase_id uuid REFERENCES public.ingredient_purchases(id) ON DELETE SET NULL,
    order_item_id uuid REFERENCES public.order_items(id) ON DELETE SET NULL,
    unit text,
    unit_cost_snapshot numeric CHECK (unit_cost_snapshot IS NULL OR unit_cost_snapshot >= 0::numeric),
    movement_reason text,
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL
);

CREATE TABLE public.ingredient_waste_records (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id),
    ingredient_id uuid NOT NULL REFERENCES public.ingredients(id),
    purchase_id uuid REFERENCES public.ingredient_purchases(id),
    stock_movement_id uuid REFERENCES public.stock_movements(id),
    quantity numeric NOT NULL CHECK (quantity > 0::numeric),
    unit text NOT NULL,
    unit_cost_snapshot numeric NOT NULL DEFAULT 0 CHECK (unit_cost_snapshot >= 0::numeric),
    total_cost numeric NOT NULL DEFAULT 0 CHECK (total_cost >= 0::numeric),
    reason text NOT NULL CHECK (reason = ANY (ARRAY['expired'::text, 'damaged'::text, 'spill'::text, 'quality_issue'::text, 'manual_adjustment'::text, 'other'::text])),
    wasted_at timestamptz NOT NULL DEFAULT now(),
    note text,
    created_by uuid REFERENCES public.profiles(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (total_cost = round(quantity * unit_cost_snapshot, 4) OR total_cost >= 0::numeric)
);

CREATE TABLE public.order_status_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
    from_status text,
    to_status text NOT NULL,
    changed_by uuid,
    changed_by_type text NOT NULL DEFAULT 'system' CHECK (changed_by_type = ANY (ARRAY['admin'::text, 'customer'::text, 'system'::text])),
    note text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.payment_status_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_id uuid NOT NULL REFERENCES public.payments(id) ON DELETE CASCADE,
    order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
    from_status text,
    to_status text NOT NULL,
    changed_by uuid,
    changed_by_type text NOT NULL DEFAULT 'system' CHECK (changed_by_type = ANY (ARRAY['admin'::text, 'customer'::text, 'system'::text])),
    note text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.overhead_expenses (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id),
    name text NOT NULL,
    category text NOT NULL DEFAULT 'other' CHECK (category = ANY (ARRAY['rent'::text, 'water'::text, 'electricity'::text, 'internet'::text, 'labor'::text, 'equipment'::text, 'transport'::text, 'marketing'::text, 'other'::text])),
    amount numeric NOT NULL DEFAULT 0 CHECK (amount >= 0::numeric),
    period text NOT NULL DEFAULT 'monthly' CHECK (period = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text])),
    is_active boolean NOT NULL DEFAULT true,
    note text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.planning_assumptions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id),
    expected_cups_per_month integer NOT NULL DEFAULT 300 CHECK (expected_cups_per_month > 0),
    operating_days_per_month integer NOT NULL DEFAULT 20 CHECK (operating_days_per_month > 0),
    target_profit_monthly numeric NOT NULL DEFAULT 0 CHECK (target_profit_monthly >= 0::numeric),
    overhead_allocation_method text NOT NULL DEFAULT 'per_cup' CHECK (overhead_allocation_method = ANY (ARRAY['per_cup'::text])),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.store_payment_settings (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    promptpay_qr_storage_path text,
    promptpay_qr_file_name text,
    promptpay_display_name text,
    is_promptpay_enabled boolean NOT NULL DEFAULT true,
    is_cash_enabled boolean NOT NULL DEFAULT true,
    updated_by uuid REFERENCES public.profiles(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (is_promptpay_enabled = true OR is_cash_enabled = true)
);

CREATE TABLE public.line_link_tokens (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,
    customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,
    line_user_id text NOT NULL,
    token_hash text NOT NULL,
    purpose text NOT NULL DEFAULT 'order_binding' CHECK (purpose = 'order_binding'::text),
    expires_at timestamptz NOT NULL CHECK (expires_at > created_at),
    used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.line_notification_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL,
    customer_id uuid REFERENCES public.customers(id) ON DELETE SET NULL,
    line_user_id text NOT NULL,
    message_type text NOT NULL,
    message_payload jsonb,
    send_status text NOT NULL DEFAULT 'pending' CHECK (send_status = ANY (ARRAY['pending'::text, 'success'::text, 'failed'::text])),
    error_message text,
    sent_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- =============================================================================
-- UNIQUE CONSTRAINTS
-- =============================================================================

ALTER TABLE public.store_members ADD CONSTRAINT store_members_store_id_user_id_key UNIQUE (store_id, user_id);
ALTER TABLE public.recipes ADD CONSTRAINT recipes_product_id_ingredient_id_key UNIQUE (product_id, ingredient_id);
ALTER TABLE public.channel_prices ADD CONSTRAINT channel_prices_product_id_channel_id_key UNIQUE (product_id, channel_id);
ALTER TABLE public.planning_assumptions ADD CONSTRAINT planning_assumptions_store_unique UNIQUE (store_id);
ALTER TABLE public.store_payment_settings ADD CONSTRAINT store_payment_settings_store_id_key UNIQUE (store_id);
ALTER TABLE public.line_link_tokens ADD CONSTRAINT line_link_tokens_token_hash_key UNIQUE (token_hash);
ALTER TABLE public.orders ADD CONSTRAINT orders_public_token_key UNIQUE (public_token);

-- =============================================================================
-- STANDALONE INDEXES (non-constraint)
-- =============================================================================

-- store_members (includes duplicate index store_members_store_user_unique — will be dropped in hardening migration)
CREATE UNIQUE INDEX store_members_store_user_unique ON public.store_members USING btree (store_id, user_id);

-- channel_prices
CREATE UNIQUE INDEX channel_prices_product_channel_unique ON public.channel_prices USING btree (store_id, product_id, channel_id);
CREATE INDEX idx_channel_prices_product_id ON public.channel_prices USING btree (product_id);
CREATE INDEX idx_channel_prices_store_id ON public.channel_prices USING btree (store_id);

-- customers
CREATE INDEX idx_customers_line_user_id ON public.customers USING btree (line_user_id);
CREATE INDEX idx_customers_store_id ON public.customers USING btree (store_id);
CREATE UNIQUE INDEX idx_customers_store_line_user_unique ON public.customers USING btree (store_id, line_user_id) WHERE (line_user_id IS NOT NULL);

-- ingredients
CREATE INDEX idx_ingredients_store_id ON public.ingredients USING btree (store_id);
CREATE INDEX idx_ingredients_store_cost_source ON public.ingredients USING btree (store_id, cost_source);
CREATE UNIQUE INDEX ingredients_store_name_unique ON public.ingredients USING btree (store_id, lower(TRIM(BOTH FROM name)));

-- ingredient_purchases
CREATE INDEX idx_ingredient_purchases_store_created_at ON public.ingredient_purchases USING btree (store_id, created_at DESC);
CREATE INDEX idx_ingredient_purchases_store_expiry ON public.ingredient_purchases USING btree (store_id, expires_at) WHERE (is_perishable = true);
CREATE INDEX idx_ingredient_purchases_store_ingredient ON public.ingredient_purchases USING btree (store_id, ingredient_id);
CREATE INDEX idx_ingredient_purchases_store_lot ON public.ingredient_purchases USING btree (store_id, lot_code) WHERE (lot_code IS NOT NULL);
CREATE INDEX idx_ingredient_purchases_store_payment_status ON public.ingredient_purchases USING btree (store_id, payment_status);
CREATE INDEX idx_ingredient_purchases_store_supplier ON public.ingredient_purchases USING btree (store_id, supplier_name);

-- ingredient_waste_records
CREATE INDEX idx_ingredient_waste_records_ingredient ON public.ingredient_waste_records USING btree (store_id, ingredient_id);
CREATE INDEX idx_ingredient_waste_records_purchase ON public.ingredient_waste_records USING btree (purchase_id) WHERE (purchase_id IS NOT NULL);
CREATE INDEX idx_ingredient_waste_records_reason ON public.ingredient_waste_records USING btree (store_id, reason, wasted_at DESC);
CREATE INDEX idx_ingredient_waste_records_store_date ON public.ingredient_waste_records USING btree (store_id, wasted_at DESC);

-- line_link_tokens
CREATE INDEX idx_line_link_tokens_customer_id ON public.line_link_tokens USING btree (customer_id);
CREATE INDEX idx_line_link_tokens_expires_at ON public.line_link_tokens USING btree (expires_at);
CREATE INDEX idx_line_link_tokens_store_line_user ON public.line_link_tokens USING btree (store_id, line_user_id);

-- line_notification_logs
CREATE INDEX idx_line_notification_logs_created_at ON public.line_notification_logs USING btree (created_at DESC);
CREATE INDEX idx_line_notification_logs_customer_id ON public.line_notification_logs USING btree (customer_id);
CREATE INDEX idx_line_notification_logs_line_user_created ON public.line_notification_logs USING btree (line_user_id, created_at DESC);
CREATE INDEX idx_line_notification_logs_line_user_id ON public.line_notification_logs USING btree (line_user_id);
CREATE INDEX idx_line_notification_logs_order_id ON public.line_notification_logs USING btree (order_id);
CREATE INDEX idx_line_notification_logs_send_status ON public.line_notification_logs USING btree (send_status);

-- order_items
CREATE INDEX idx_order_items_order_id ON public.order_items USING btree (order_id);
CREATE INDEX idx_order_items_product_id ON public.order_items USING btree (product_id);

-- order_status_logs
CREATE INDEX idx_order_status_logs_created_at ON public.order_status_logs USING btree (created_at DESC);
CREATE INDEX idx_order_status_logs_order_id ON public.order_status_logs USING btree (order_id);

-- orders
CREATE INDEX idx_orders_created_at ON public.orders USING btree (created_at);
CREATE INDEX idx_orders_pickup_time ON public.orders USING btree (pickup_time);
CREATE INDEX idx_orders_public_token ON public.orders USING btree (public_token);
CREATE INDEX idx_orders_store_id ON public.orders USING btree (store_id);
CREATE INDEX idx_orders_store_payment_status_created ON public.orders USING btree (store_id, payment_status, created_at DESC);
CREATE INDEX idx_orders_store_status_created ON public.orders USING btree (store_id, status, created_at DESC);
CREATE UNIQUE INDEX orders_store_order_no_unique ON public.orders USING btree (store_id, order_no);

-- overhead_expenses
CREATE INDEX idx_overhead_expenses_store_id ON public.overhead_expenses USING btree (store_id);
CREATE INDEX idx_overhead_expenses_store_active ON public.overhead_expenses USING btree (store_id, is_active);

-- payment_status_logs
CREATE INDEX idx_payment_status_logs_created_at ON public.payment_status_logs USING btree (created_at DESC);
CREATE INDEX idx_payment_status_logs_order_id ON public.payment_status_logs USING btree (order_id);
CREATE INDEX idx_payment_status_logs_payment_id ON public.payment_status_logs USING btree (payment_id);

-- payments
