-- =============================================================================
-- FUNCTIONS
-- =============================================================================

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.valora_set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.valora_set_ingredient_purchase_unit_cost()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.normalized_quantity IS NULL OR NEW.normalized_quantity <= 0 THEN
    NEW.normalized_quantity = NEW.quantity * COALESCE(NULLIF(NEW.conversion_factor, 0), 1);
  END IF;

  IF NEW.normalized_quantity <= 0 THEN
    RAISE EXCEPTION 'normalized_quantity must be greater than 0';
  END IF;

  NEW.unit_cost_snapshot = NEW.total_cost / NEW.normalized_quantity;
  NEW.updated_at = now();

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_order_item_totals()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  new.total_price = new.quantity * new.unit_price;
  new.total_cost = new.quantity * new.unit_cost;
  new.line_profit = new.total_price - new.total_cost;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.recalculate_order_totals(target_order_id uuid)
RETURNS void
LANGUAGE plpgsql
AS $function$
begin
  update public.orders
  set
    subtotal = coalesce((
      select sum(total_price)
      from public.order_items
      where order_id = target_order_id
    ), 0),

    total_cost = coalesce((
      select sum(total_cost)
      from public.order_items
      where order_id = target_order_id
    ), 0),

    total_amount = greatest(
      coalesce((
        select sum(total_price)
        from public.order_items
        where order_id = target_order_id
      ), 0) - discount_amount,
      0
    ),

    gross_profit =
      greatest(
        coalesce((
          select sum(total_price)
          from public.order_items
          where order_id = target_order_id
        ), 0) - discount_amount,
        0
      )
      - coalesce((
          select sum(total_cost)
          from public.order_items
          where order_id = target_order_id
        ), 0)
      - channel_fee,

    updated_at = now()
  where id = target_order_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.recalculate_order_after_item_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.recalculate_order_totals(old.order_id);
    return old;
  else
    perform public.recalculate_order_totals(new.order_id);
    return new;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_order_status_columns()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.order_status := NEW.status;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_order_status_legacy_status()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  if new.order_status is distinct from old.order_status then
    new.status = new.order_status;
  elsif new.status is distinct from old.status then
    new.order_status = new.status;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_payment_to_order()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'paid' then
    update public.orders
    set
      payment_status = 'paid',
      order_status = case
        when order_status in ('draft', 'pending_payment', 'waiting_payment_review') then 'accepted'
        else order_status
      end,
      status = case
        when status in ('draft', 'pending_payment', 'waiting_payment_review') then 'accepted'
        else status
      end,
      updated_at = now()
    where id = new.order_id;

  elsif new.status = 'rejected' then
    update public.orders
    set
      payment_status = 'rejected',
      order_status = 'pending_payment',
      status = 'pending_payment',
      updated_at = now()
    where id = new.order_id;

  elsif new.status in ('pending', 'pending_review') then
    update public.orders
    set
      payment_status = 'pending_review',
      order_status = 'waiting_payment_review',
      status = 'waiting_payment_review',
      updated_at = now()
    where id = new.order_id;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.log_order_status_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  if old.order_status is distinct from new.order_status then
    insert into public.order_status_logs (
      order_id,
      from_status,
      to_status,
      changed_by_type,
      note
    )
    values (
      new.id,
      old.order_status,
      new.order_status,
      'system',
      'Auto log from orders.order_status update'
    );
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.log_payment_status_change()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
begin
  if old.status is distinct from new.status then
    insert into public.payment_status_logs (
      payment_id,
      order_id,
      from_status,
      to_status,
      changed_by_type,
      note
    )
    values (
      new.id,
      new.order_id,
      old.status,
      new.status,
      'system',
      'Auto log from payments.status update'
    );
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_store_member(_store_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
AS $function$
  select exists (
    select 1 from public.store_members sm
    where sm.store_id = _store_id and sm.user_id = auth.uid()
  );
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
RETURNS event_trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
      RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

