CREATE TRIGGER trg_channel_prices_updated_at BEFORE UPDATE ON public.channel_prices FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_customers_updated_at BEFORE UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_ingredient_purchases_set_unit_cost BEFORE INSERT OR UPDATE ON public.ingredient_purchases FOR EACH ROW EXECUTE FUNCTION valora_set_ingredient_purchase_unit_cost();
CREATE TRIGGER trg_ingredient_purchases_updated_at BEFORE UPDATE ON public.ingredient_purchases FOR EACH ROW EXECUTE FUNCTION valora_set_updated_at();
CREATE TRIGGER trg_ingredients_updated_at BEFORE UPDATE ON public.ingredients FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_calculate_order_item_totals BEFORE INSERT OR UPDATE ON public.order_items FOR EACH ROW EXECUTE FUNCTION calculate_order_item_totals();
CREATE TRIGGER trg_recalculate_order_after_item_delete AFTER DELETE ON public.order_items FOR EACH ROW EXECUTE FUNCTION recalculate_order_after_item_change();
CREATE TRIGGER trg_recalculate_order_after_item_insert AFTER INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION recalculate_order_after_item_change();
CREATE TRIGGER trg_recalculate_order_after_item_update AFTER UPDATE ON public.order_items FOR EACH ROW EXECUTE FUNCTION recalculate_order_after_item_change();
CREATE TRIGGER trg_log_order_status_change AFTER UPDATE OF order_status ON public.orders FOR EACH ROW EXECUTE FUNCTION log_order_status_change();
CREATE TRIGGER trg_orders_updated_at BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_sync_order_status_columns BEFORE INSERT OR UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION sync_order_status_columns();
CREATE TRIGGER trg_sync_order_status_legacy_status BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION sync_order_status_legacy_status();
CREATE TRIGGER trg_log_payment_status_change AFTER UPDATE OF status ON public.payments FOR EACH ROW EXECUTE FUNCTION log_payment_status_change();
CREATE TRIGGER trg_payments_updated_at BEFORE UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_sync_payment_to_order AFTER INSERT OR UPDATE OF status ON public.payments FOR EACH ROW EXECUTE FUNCTION sync_payment_to_order();
CREATE TRIGGER trg_product_addon_recipes_updated_at BEFORE UPDATE ON public.product_addon_recipes FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_product_addons_updated_at BEFORE UPDATE ON public.product_addons FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_product_categories_updated_at BEFORE UPDATE ON public.product_categories FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_products_updated_at BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_recipes_updated_at BEFORE UPDATE ON public.recipes FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_sales_channels_updated_at BEFORE UPDATE ON public.sales_channels FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_store_payment_settings_updated_at BEFORE UPDATE ON public.store_payment_settings FOR EACH ROW EXECUTE FUNCTION set_updated_at();

