-- =============================================================================
-- RLS POLICIES
-- =============================================================================

-- channel_prices
CREATE POLICY "Public can read channel prices" ON public.channel_prices FOR SELECT TO anon, authenticated USING (true);

-- customers
CREATE POLICY "Public can insert customers" ON public.customers FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY "Store members can read customers" ON public.customers FOR SELECT TO authenticated USING (is_store_member(store_id));

-- ingredient_purchases
CREATE POLICY "ingredient_purchases_select_manager_only" ON public.ingredient_purchases FOR SELECT TO public USING (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = ingredient_purchases.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));
CREATE POLICY "ingredient_purchases_insert_manager_only" ON public.ingredient_purchases FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = ingredient_purchases.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));
CREATE POLICY "ingredient_purchases_update_manager_only" ON public.ingredient_purchases FOR UPDATE TO public USING (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = ingredient_purchases.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text]))) WITH CHECK (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = ingredient_purchases.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));

-- order_items
CREATE POLICY "Public can insert order items" ON public.order_items FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY "Store members can read order items" ON public.order_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM orders o WHERE o.id = order_items.order_id AND is_store_member(o.store_id)));

-- order_status_logs
CREATE POLICY "Store members can insert order status logs" ON public.order_status_logs FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM orders o WHERE o.id = order_status_logs.order_id AND is_store_member(o.store_id)));

-- orders
CREATE POLICY "Public can insert orders" ON public.orders FOR INSERT TO anon, authenticated WITH CHECK (channel = ANY (ARRAY['web_order'::text, 'line_rich_menu'::text]) AND order_source = ANY (ARRAY['web_order'::text, 'line_rich_menu'::text]));
CREATE POLICY "Store members can read orders" ON public.orders FOR SELECT TO authenticated USING (is_store_member(store_id));
CREATE POLICY "Store members can update orders" ON public.orders FOR UPDATE TO authenticated USING (is_store_member(store_id)) WITH CHECK (is_store_member(store_id));

-- payment_status_logs
CREATE POLICY "Store members can insert payment status logs" ON public.payment_status_logs FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM orders o WHERE o.id = payment_status_logs.order_id AND is_store_member(o.store_id)));

-- payments
CREATE POLICY "Public can insert payments" ON public.payments FOR INSERT TO anon, authenticated WITH CHECK (status = ANY (ARRAY['pending'::text, 'pending_review'::text]));
CREATE POLICY "Store members can read payments" ON public.payments FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM orders o WHERE o.id = payments.order_id AND is_store_member(o.store_id)));
CREATE POLICY "Store members can update payments" ON public.payments FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM orders o WHERE o.id = payments.order_id AND is_store_member(o.store_id))) WITH CHECK (EXISTS (SELECT 1 FROM orders o WHERE o.id = payments.order_id AND is_store_member(o.store_id)));

-- product_categories
CREATE POLICY "Public can read product categories" ON public.product_categories FOR SELECT TO anon, authenticated USING (true);

-- products
CREATE POLICY "Public can read active products" ON public.products FOR SELECT TO anon, authenticated USING (is_active = true);

-- profiles
CREATE POLICY "Users can read own profile" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());

-- sales_channels
CREATE POLICY "Public can read active sales channels" ON public.sales_channels FOR SELECT TO anon, authenticated USING (is_active = true);

-- store_members
CREATE POLICY "store_members by store" ON public.store_members FOR ALL TO public USING (is_store_member(store_id)) WITH CHECK (is_store_member(store_id));

-- store_payment_settings
CREATE POLICY "store_payment_settings_select_store_members" ON public.store_payment_settings FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = store_payment_settings.store_id AND sm.user_id = auth.uid()));
CREATE POLICY "store_payment_settings_insert_managers" ON public.store_payment_settings FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = store_payment_settings.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));
CREATE POLICY "store_payment_settings_update_managers" ON public.store_payment_settings FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = store_payment_settings.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text]))) WITH CHECK (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = store_payment_settings.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));
CREATE POLICY "store_payment_settings_delete_managers" ON public.store_payment_settings FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM store_members sm WHERE sm.store_id = store_payment_settings.store_id AND sm.user_id = auth.uid() AND sm.role::text = ANY (ARRAY['owner'::text, 'admin'::text, 'manager'::text])));

-- =============================================================================
-- EVENT TRIGGER (auto-enable RLS on new tables)
-- =============================================================================

CREATE EVENT TRIGGER ensure_rls
ON ddl_command_end
EXECUTE FUNCTION public.rls_auto_enable();

-- =============================================================================
-- GRANTS (default Supabase pattern: all privileges to anon, authenticated, service_role)
-- =============================================================================

GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
